// Compares functions/src/mychama/pay/fees.ts with fee-vectors.json (generated by the Chama Python engine).
//   node scripts/mychama/test-fees.mjs        (Node >= 22.18, or add --experimental-strip-types)
import { readFileSync } from "node:fs";
import * as fees from "../../functions/src/mychama/pay/fees.ts";

const v = JSON.parse(readFileSync(new URL("./fee-vectors.json", import.meta.url), "utf8"));
const fn = {
  contribution: (r) => fees.contributionFees(r.net),
  mgr: (r) => fees.mgrContributionFees(r.net),
  loan: (r) => fees.loanRepaymentFees(r.net, r.plan),
};
let bad = 0;
for (const r of v.rows) {
  const got = fn[r.fn](r);
  for (const k of ["net", "gross", "paystackFee", "ourFee"]) {
    if (got[k] !== r.out[k]) {
      bad++;
      if (bad <= 10) console.error(`MISMATCH ${r.fn} plan=${r.plan ?? "-"} net=${r.net} ${k}: ts=${got[k]} py=${r.out[k]}`);
    }
  }
}
for (const [plan, allowed] of Object.entries(v.plans_online)) {
  if (fees.onlineCollectionAllowed(plan) !== allowed) { bad++; console.error(`MISMATCH onlineCollection ${plan}`); }
}
if (fees.onlineCollectionAllowed("nope") !== false) { bad++; console.error("unknown plan must behave as free"); }
console.log(`${v.rows.length} vectors compared, ${bad} mismatches`);
process.exit(bad ? 1 : 0);
